CREATE DATABASE IF NOT EXISTS phone_dw CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE phone_dw;
CREATE TABLE IF NOT EXISTS dim_thoi_gian (thoi_gian_key INT PRIMARY KEY, ngay DATE NOT NULL UNIQUE, nam INT NOT NULL, quy INT NOT NULL, thang INT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dim_san_pham (san_pham_key INT AUTO_INCREMENT PRIMARY KEY, ma_sku VARCHAR(30) NOT NULL UNIQUE, ten_san_pham VARCHAR(120), thuong_hieu VARCHAR(100), ram_gb INT, bo_nho_gb INT, mau_sac VARCHAR(30)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dim_cua_hang (cua_hang_key INT AUTO_INCREMENT PRIMARY KEY, ma_cua_hang VARCHAR(20) NOT NULL, ten_cua_hang VARCHAR(100), tinh_thanh VARCHAR(100), khu_vuc_quan_ly VARCHAR(100) NOT NULL, ngay_hieu_luc DATE NOT NULL, ngay_het_han DATE NOT NULL, is_current BOOLEAN NOT NULL, UNIQUE(ma_cua_hang,ngay_hieu_luc), CHECK(ngay_hieu_luc<ngay_het_han)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dim_khach_hang (khach_hang_key INT AUTO_INCREMENT PRIMARY KEY, ma_khach_hang VARCHAR(20) NOT NULL UNIQUE, ho_ten VARCHAR(100), tinh_thanh VARCHAR(100)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dim_kenh_ban (kenh_ban_key INT AUTO_INCREMENT PRIMARY KEY, ma_kenh VARCHAR(20) NOT NULL UNIQUE, ten_kenh VARCHAR(100)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS dim_khuyen_mai (khuyen_mai_key INT AUTO_INCREMENT PRIMARY KEY, ma_khuyen_mai VARCHAR(20) NOT NULL UNIQUE, ten_khuyen_mai VARCHAR(100)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fact_ban_hang (ban_hang_key BIGINT AUTO_INCREMENT PRIMARY KEY, ma_chi_tiet VARCHAR(30) NOT NULL UNIQUE, ma_don_hang VARCHAR(25) NOT NULL, thoi_gian_key INT NOT NULL, san_pham_key INT NOT NULL, cua_hang_key INT NOT NULL, khach_hang_key INT NOT NULL, kenh_ban_key INT NOT NULL, khuyen_mai_key INT NOT NULL, so_luong INT NOT NULL CHECK(so_luong>0), don_gia DECIMAL(18,2) NOT NULL CHECK(don_gia>=0), giam_gia DECIMAL(18,2) NOT NULL CHECK(giam_gia>=0), doanh_thu DECIMAL(18,2) NOT NULL CHECK(doanh_thu>=0), gia_von DECIMAL(18,2) NOT NULL CHECK(gia_von>=0), FOREIGN KEY(thoi_gian_key) REFERENCES dim_thoi_gian(thoi_gian_key), FOREIGN KEY(san_pham_key) REFERENCES dim_san_pham(san_pham_key), FOREIGN KEY(cua_hang_key) REFERENCES dim_cua_hang(cua_hang_key), FOREIGN KEY(khach_hang_key) REFERENCES dim_khach_hang(khach_hang_key), FOREIGN KEY(kenh_ban_key) REFERENCES dim_kenh_ban(kenh_ban_key), FOREIGN KEY(khuyen_mai_key) REFERENCES dim_khuyen_mai(khuyen_mai_key), INDEX ix_order(ma_don_hang)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS fact_tra_hang (tra_hang_key BIGINT AUTO_INCREMENT PRIMARY KEY, ma_chi_tiet_tra VARCHAR(30) NOT NULL UNIQUE, ban_hang_key BIGINT NOT NULL, thoi_gian_key INT NOT NULL, so_luong_tra INT NOT NULL CHECK(so_luong_tra>0), tien_hoan DECIMAL(18,2) NOT NULL CHECK(tien_hoan>=0), gia_von_hoan DECIMAL(18,2) NOT NULL CHECK(gia_von_hoan>=0), FOREIGN KEY(ban_hang_key) REFERENCES fact_ban_hang(ban_hang_key), FOREIGN KEY(thoi_gian_key) REFERENCES dim_thoi_gian(thoi_gian_key)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS etl_log (log_id BIGINT AUTO_INCREMENT PRIMARY KEY, run_id VARCHAR(32) NOT NULL, buoc VARCHAR(40), bang VARCHAR(80), so_dong_doc INT DEFAULT 0, so_dong_nap INT DEFAULT 0, so_dong_loai INT DEFAULT 0, ghi_chu TEXT, status VARCHAR(20), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(run_id));
CREATE TABLE IF NOT EXISTS etl_data_quality (dq_id BIGINT AUTO_INCREMENT PRIMARY KEY, run_id VARCHAR(32) NOT NULL, bang VARCHAR(80), loai_kiem_tra VARCHAR(80), so_dong_truoc INT, so_dong_sau INT, cach_xu_ly TEXT, INDEX(run_id));
CREATE TABLE IF NOT EXISTS etl_reject (reject_id BIGINT AUTO_INCREMENT PRIMARY KEY, run_id VARCHAR(32) NOT NULL, bang VARCHAR(80), source_id VARCHAR(50), reason VARCHAR(100), payload LONGTEXT, INDEX(run_id));
CREATE TABLE IF NOT EXISTS stg_import (staging_id BIGINT AUTO_INCREMENT PRIMARY KEY, run_id VARCHAR(32) NOT NULL, source_table VARCHAR(80), source_id VARCHAR(50), payload LONGTEXT, INDEX(run_id));
